// mod.json
{
  "entrypoint": "main.lua",
  "permissions": ["chat.send", "player.read", "server.command.register"],
  "requires": { "capabilities": { "player.looking_at.read": "1.0.0" } }
}

-- main.lua
mod.command("onde", function(ctx)
  if ctx.player == nil then return end
  local alvo = ctx.player.looking_at()
  if alvo == nil then
    ctx.player.send_message("Olhe para um bloco.")
    return
  end
  ctx.player.send_message("Alvo: " .. alvo.x .. ", " .. alvo.y .. ", " .. alvo.z)
end)

// mod.json: callback de ciclo de vida
{ "events": { "server_started": "on_server_started" } }

-- main.lua: evento global cancelável
mod.on("action_attempt", function(ctx)
  if ctx.action == "block.break"
    and ctx.target.id == "minecraft:obsidian" then
    return false
  end
end)

function on_server_started(ctx)
  ctx.log.info("mod carregado")
end

return { on_server_started = on_server_started }
